private boolean unlink(ListNodeImpl<E> node) {
    if (node == null || node.next == null) {
        throw new IllegalArgumentException();
    }
    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.next = null;
    node.prev = null;
    return true;
}

boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false; // Handle null node gracefully
    }

    ListNodeImpl<E> prev = null, curr = head;
    while (curr != node && curr != null) {
        prev = curr;
        curr = curr.getNextNode();
    }

    if (curr == node) { // Node found and is part of the list
        if (prev == null) {
            // Node is head, move head to next and adjust current pointer
            head = curr.getNextNode();
        } else {
            // Node is in middle or tail, adjust pointers
            prev.setNextNode(curr.getNextNode());
        }
        size--; // Decrement size as the node is removed
        return true;
    } else {
        // Node not found in the list
        return false;
    }
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }
    if (head == null) {
        return false;
    }
    if (head == node) {
        head = node.next;
        return true;
    }
    ListNodeImpl<E> current = head;
    while (current.next != node) {
        current = current.next;
    }
    if (current.next == node) {
        current.next = node.next;
        return true;
    }
    return false;
}

