OuterFaceCirculator function(Predicate<Node> predicate,Node start,Node stop,int dir){
    // Check if the predicate is null
    if(predicate == null){
      throw new IllegalArgumentException("Predicate cannot be null");
    }

    // Check if the start node is null
    if(start == null){
      throw new IllegalArgumentException("Start node cannot be null");
    }

    // Check if the stop node is null
    if(stop == null){
      throw new IllegalArgumentException("Stop node cannot be null");
    }

    // Check if the direction is invalid
    if(dir < 0 || dir > 3){
      throw new IllegalArgumentException("Direction must be between 0 and 3");
    }

    Node next;
    while((next = selectNodeDir(predicate,start,dir)) == null && (dir + 1) % 4 != dir){
      dir = (dir + 1) % 4;
    }

    if(next == null){
      next = stop;
    }

    return new OuterFaceCirculator(next);
  }

  private Node selectNodeDir(Predicate<Node> predicate,Node node,int dir){
    if(node.isLeaf()){
      return null;
    }

    Node next;
    switch(dir){
      case 0: next = node.getLeft(); break;
      case 1: next = node; break;
      case 2: next = node.getRight(); break;
      case 3: next = node.getParent(); break;
    }

    if(predicate.test(next)){
      return next;
    }

    return null;
  }

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node curr = start;
    while (curr != stop) {
        if (predicate.test(curr)) {
            return new OuterFaceCirculator(curr);
        }
        curr = getNextNode(curr, dir);
        if (curr == null) break;
    }
    return new OuterFaceCirculator(stop);
}

private Node getNextNode(Node current, int direction) {
    if (direction == 0) { // Left
        current = current.getLeft();
    } else if (direction == 1) { // Right
