private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null || graph.isEmpty() || vertices.isEmpty()) {
        return false;
    }

    for (V vertex : vertices) {
        Set<V> neighbors = graph.neighbors(vertex);
        if (vertices.size() != neighbors.size()) {
            return false;
        }
        for (V neighbor : vertices) {
            if (neighbor == vertex || !neighbors.contains(neighbor)) {
                return false;
            }
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    for (V v : vertices) {
        Map<V, Boolean> neighbors = new HashMap<>();
        for (V u : vertices) {
            if (u != v) {
                neighbors.put(u, graph.hasEdge(v, u));
            }
        }
        if (!checkAllNeighbors(vertices, neighbors)) {
            return false;
        }
    }
    return true;
}

