public static int writeTo(final DataOutput out,LinkedBuffer node) throws IOException {
    // Create a ByteBuffer to write the LinkedBuffer's data
    ByteBuffer byteBuffer = ByteBuffer.allocate(node.getLruEntry().getFilePointer());
    // Traverse the LinkedBuffer to copy its data to the ByteBuffer
    while (node != null) {
        byteBuffer.put(node.getData());
        node = node.getNext();
    }
    // Write the size of the ByteBuffer to the DataOutput
    out.writeByte(byteBuffer.position());
    // Write the ByteBuffer's content to the DataOutput
    out.write(byteBuffer.array());
    // Return the total content size of the ByteBuffer
    return byteBuffer.position();
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    out.writeBoolean(true); // Write the presence of data as a boolean in binary
    for (Object obj : node.getElements()) {
        out.writeObject(obj); // Write each elem as a specific type
    }

    // Total count of elements written plus the preceding boolean
    return node.getElements().length + 1;
}

