        int size = 0;
        LinkedNode<Object[]> head = node._head;
        while (head != null) {
            if (head.getNodeData() instanceof byte[]) {
                byte[] data = (byte[]) head.getNodeData();
                out.write(data);
                size += data.length;
            }
            head = head.getNextNode();
        }
        return size;
    }

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    OutputStream os = out; // Convert the DataOutput to OutputStream
    if (node == null || node.getData() == null || node.getData().length == 0) {
        return 0; // Return 0 if the node or its data is null or empty
    }
    os.write(node.getData(), 0, node.getData().length); // Write the data of the Node to the OutputStream
    return node.getData().length; // Return the total content size of the buffer
}

